#!/usr/bin/env python3
"""Add draft guides only for approved ratio-share sources lacking existing bindings."""
import gzip,hashlib,json
from fractions import Fraction as F
from pathlib import Path
D=Path(__file__).resolve().parent;ROOT=Path(__file__).resolve().parents[3]
STATE=json.loads(gzip.decompress((D/'bulk-state.json.gz').read_bytes()))
def sha(o):return hashlib.sha256(json.dumps(o,sort_keys=True,ensure_ascii=False,separators=(',',':')).encode()).hexdigest()
def main():
 audit=json.loads((D/'ratio43-audit-v0.1.json').read_text());cache={};bindings=[]
 for a in audit['items']:
  if a['status']!='approved' or a['existing_tutoring_binding']:continue
  row=next(r for r in STATE['records'] if r['question_id']==a['question_id'])
  if row['source_file'] not in cache:cache[row['source_file']]={q['id']:q for q in json.loads((ROOT/row['source_file']).read_text())['items']}
  q=cache[row['source_file']][a['question_id']];assert sha(q)==a['source_record_sha256']
  p=a['parameters'];total=F(p['total']);parts=p['parts'];selected=p['selected_part'];part=parts[selected-1];units=sum(parts);share=total*F(part,units)
  other=parts[0] if selected==2 else parts[1]
  diagnostic={'prompt':f'Before calculating, how do you interpret the ratio {parts[0]} : {parts[1]} for this total?','choices':[
   {'id':'sum-parts','text':f'There are {parts[0]} + {parts[1]} = {units} equal parts in all; the requested person gets {part} of them.','role':'correct-rule','feedback':'Yes. The ratio parts describe portions of the whole. Add all parts to find the total number of equal portions, then take the requested number.'},
   {'id':'ratio-number-as-denominator','text':f'The requested person gets {part} parts out of only {part} total parts.','role':'omit-other-part-hypothesis','feedback':f'The other person also receives {other} parts. Include both ratio numbers when finding the total number of parts.'},
   {'id':'ratio-as-peso-amount','text':'The second person receives b pesos for every peso in the total.','role':'ratio-unit-confusion','feedback':'The ratio numbers are unitless part counts, not pesos. First find the value of one part from the total.'},
   {'id':'multiply-only','text':f'Multiply the total by {part} without dividing by {units} total parts.','role':'part-whole-fraction-hypothesis','feedback':f'The requested share is {part} parts out of {units} parts, so use {part}/{units} of the total.'},
   {'id':'unsure','text':'I am unsure, guessed, or selected by mistake.','role':'uncertain','feedback':'No cause is established. Write the number of parts for each person, then count all parts together.'}], 'confirmation':'Was that your original interpretation, a method you chose after seeing these choices, a guess, or a misclick?'}
  bindings.append({'question_id':q['id'],'source_file':row['source_file'],'source_record_sha256':a['source_record_sha256'],'bank_status_at_authoring':'approved','difficulty':q.get('difficulty'),'language':q.get('language'),'concept_family':'ratio-part-to-whole-sharing','diagnostic_template':'add-ratio-parts-before-taking-share','diagnostic':diagnostic,'verified_answer':{'option_id':q['answer_option_id'],'value':str(share),'unit':'PHP','fraction_of_total':f'{part}/{units}','method':'requested part ÷ total parts × total amount','checks':['all ratio parts included in denominator','computed share agrees with stored key','exactly one option matches']},'worked_solution':{'steps':[f'Total ratio parts: {" + ".join(map(str,parts))} = {units}.',f'Value of one part: ₱{int(total)} ÷ {units} = ₱{int(total/units)}.',f'The requested share has {part} parts: {part} × ₱{int(total/units)} = ₱{int(share)}.'], 'hints':['Add every number in the ratio; that is the number of equal parts in the whole.','Divide the total amount by the number of parts to find one part.','Multiply one part by the number belonging to the requested recipient.'],'shortcut':f'The requested recipient gets {part}/{units} of the total. The denominator is the sum of all ratio terms.'},'transfer':{'approved_question_id':None,'reason':'The existing approved pool is predominantly two-person allocation with repeated parameter sets; no distinct, unfamiliar approved transfer is identified in this ratio batch.'},'outcome_contract':{'diagnostic_is_assisted':True,'misconception_is_hypothesis_only':True,'confirmation_required_for_persistent_hypothesis':True,'uncertain_or_misclick_assigns_hypothesis':False,'diagnostic_correctness_is_not_mastery':True,'independent_transfer_required_for_mastery':True},'status':'draft','editorial_review':None,'runtime_eligible':False})
 side={'schema_version':'dexter-ratio43-guide-draft-v0.1','baseline_commit':'32db7861a2d89435c4019a3a7a66b41dd4fd604a','status':'draft','runtime_eligible':False,'independent_review':None,'learner_evidence':None,'bindings':bindings,'already_covered_ids':[x['question_id'] for x in audit['items'] if x['status']=='approved' and x['existing_tutoring_binding']],'excluded_nonapproved_ids':[x['question_id'] for x in audit['items'] if x['status']!='approved'],'notes':['Only nine uncovered approved share questions receive new bindings; 20 existing pilot/overlay bindings are retained unchanged.','All nine new bindings reuse one two-person ratio-share family and are practice support, not independent mastery evidence.','The 14 other ratio/proportion records are all reviewed or draft and are excluded.','No transfer question is promoted or invented; reviewer and runtime fields remain pending.']}
 (D/'ratio43-guide-draft-v0.1.json').write_text(json.dumps(side,ensure_ascii=False,indent=2)+'\n');print('incremental draft bindings',len(bindings),'already covered',len(side['already_covered_ids']),'excluded nonapproved',len(side['excluded_nonapproved_ids']))
if __name__=='__main__':main()
